(451, 102, '_company_website', 'https://vng.com.vn'),
(452, 102, '_nhomg_overview', 'VNG là công ty công nghệ Việt Nam hoạt động trong các lĩnh vực trò chơi trực tuyến, nền tảng kết nối, tài chính số và giải pháp công nghệ doanh nghiệp.'),
(453, 102, '_nhomg_key_skills', 'HTML5, CSS3, JavaScript\r\n\r\n\r\n\r\nReact.js\r\n\r\n\r\n\r\nResponsive Web Design\r\n\r\n\r\n\r\nREST API\r\n\r\n\r\n\r\nGit, GitHub'),
(454, 102, '_nhomg_why_love', 'Bạn có thể biến các bản thiết kế giao diện thành sản phẩm web thực tế, tối ưu trải nghiệm người dùng và học cách phát triển những ứng dụng phục vụ nhiều người.'),
(455, 102, '_nhomg_location_detail', 'Frontend Developer'),
(456, 102, '_nhomg_highlights', 'Phù hợp với người yêu thích giao diện web.\r\n\r\n\r\n\r\nCó cơ hội phối hợp với UI/UX Designer và Backend Developer.\r\n\r\n\r\n\r\nRèn luyện kỹ năng tối ưu hiệu năng và trải nghiệm người dùng.'),
(457, 102, '_nhomg_rating', '4.3'),
(458, 102, '_nhomg_photos', ''),
(459, 102, '_heateor_sss_meta', 'a:2:{s:7:\"sharing\";i:0;s:16:\"vertical_sharing\";i:0;}'),
(460, 105, '_edit_lock', '1793147578:1'),
(461, 104, '_edit_last', '1'),
(462, 104, '_company_name', 'FPT Software'),
(463, 104, '_job_location', 'TP.Hồ Chí Minh'),
(464, 104, '_application', ''),
(465, 104, '_company_website', 'https://fptsoftware.com'),
(466, 104, '_nhomg_overview', 'FPT Software là doanh nghiệp cung cấp dịch vụ công nghệ thông tin và phát triển phần mềm cho khách hàng trong nước và quốc tế. Công ty triển khai các giải pháp phần mềm, chuyển đổi số, điện toán đám mây và trí tuệ nhân tạo.'),
(467, 104, '_nhomg_key_skills', 'PHP, Laravel hoặc Java Spring Boot\r\n\r\n\r\n\r\nMySQL, thiết kế cơ sở dữ liệu\r\n\r\n\r\n\r\nRESTful API\r\n\r\n\r\n\r\nGit, GitHub\r\n\r\n\r\n\r\nTư duy giải quyết vấn đề'),
(468, 104, '_nhomg_why_love', 'Bạn có cơ hội tham gia xây dựng hệ thống backend thực tế, làm việc với nhóm phát triển và cải thiện kỹ năng lập trình thông qua các dự án phần mềm.'),
(469, 104, '_nhomg_location_detail', 'Backend Developer'),
(470, 104, '_nhomg_highlights', 'Cơ hội tiếp xúc với dự án công nghệ quy mô lớn.\r\n\r\n\r\n\r\nMôi trường làm việc theo nhóm.\r\n\r\n\r\n\r\nCó thể phát triển chuyên môn về backend, cloud và AI.'),
(471, 104, '_nhomg_rating', '4'),
(472, 104, '_nhomg_photos', '112'),
(473, 104, '_heateor_sss_meta', 'a:2:{s:7:\"sharing\";i:0;s:16:\"vertical_sharing\";i:0;}'),
(474, 106, '_edit_lock', '1793150779:1'),
