(476, 106, '_company_name', 'MoMo'),
(477, 106, '_job_location', 'TP.Hồ Chí Minh'),
(478, 106, '_application', ''),
(479, 106, '_company_website', 'https://momo.careers'),
(480, 106, '_nhomg_overview', 'MoMo là nền tảng tài chính số của Việt Nam, cung cấp các dịch vụ thanh toán, chuyển tiền, thanh toán hóa đơn và nhiều tiện ích tài chính trên ứng dụng di động.'),
(481, 106, '_nhomg_key_skills', 'Java, Kotlin hoặc Go\r\n\r\n\r\n\r\nCấu trúc dữ liệu và giải thuật\r\n\r\n\r\n\r\nSQL và NoSQL\r\n\r\n\r\n\r\nREST API, Microservices\r\n\r\n\r\n\r\nUnit Testing'),
(482, 106, '_nhomg_why_love', 'Bạn được tìm hiểu cách xây dựng các hệ thống phần mềm phục vụ giao dịch số, chú trọng độ ổn định, hiệu năng và trải nghiệm của người dùng.'),
(483, 106, '_nhomg_location_detail', 'Software Engineer'),
(484, 106, '_nhomg_highlights', 'Làm việc với các bài toán kỹ thuật thực tế.\r\n\r\n\r\n\r\nTìm hiểu hệ thống phân tán và bảo mật ứng dụng.\r\n\r\n\r\n\r\nCó cơ hội học hỏi về công nghệ tài chính số.'),
(485, 106, '_nhomg_rating', '4'),
(486, 106, '_nhomg_photos', ''),
(487, 106, '_heateor_sss_meta', 'a:2:{s:7:\"sharing\";i:0;s:16:\"vertical_sharing\";i:0;}'),
