(491, 107, '_job_location', 'Hà Nội'),
(492, 107, '_application', ''),
(493, 107, '_company_website', 'https://viettel.com.vn'),
(494, 107, '_nhomg_overview', 'Viettel là tập đoàn hoạt động trong lĩnh vực viễn thông và công nghệ, với các mảng kinh doanh liên quan đến hạ tầng mạng, dịch vụ số, an ninh mạng và giải pháp công nghệ.'),
(495, 107, '_nhomg_key_skills', 'Linux, Bash hoặc Python\r\n\r\n\r\n\r\nDocker, Kubernetes\r\n\r\n\r\n\r\nCI/CD\r\n\r\n\r\n\r\nGitLab CI hoặc Jenkins\r\n\r\n\r\n\r\nCloud Computing, giám sát hệ thống'),
(496, 107, '_nhomg_why_love', 'Bạn có thể tìm hiểu cách triển khai phần mềm tự động, quản lý hạ tầng và cải thiện độ ổn định của hệ thống.');
INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(497, 107, '_nhomg_location_detail', 'DevOps Engineer'),
(498, 107, '_nhomg_highlights', 'Tiếp cận công nghệ hạ tầng và mạng.\r\n\r\n\r\n\r\nHọc cách tự động hóa quy trình triển khai.\r\n\r\n\r\n\r\nPhát triển kỹ năng vận hành hệ thống quy mô lớn.'),
