(507, 108, '_company_website', 'https://careers.shopee.vn'),
(508, 108, '_nhomg_overview', 'Shopee là nền tảng thương mại điện tử hoạt động tại nhiều thị trường Đông Nam Á và Đài Loan, kết nối người mua, người bán và các dịch vụ hỗ trợ thương mại điện tử.'),
(509, 108, '_nhomg_key_skills', 'Digital Marketing\r\n\r\n\r\n\r\nSEO và SEM cơ bản\r\n\r\n\r\n\r\nGoogle Analytics\r\n\r\n\r\n\r\nContent Marketing\r\n\r\n\r\n\r\nExcel và phân tích dữ liệu'),
(510, 108, '_nhomg_why_love', 'Bạn có cơ hội kết hợp sự sáng tạo với phân tích dữ liệu để xây dựng chiến dịch tiếp thị và cải thiện hiệu quả kinh doanh trực tuyến.'),
(511, 108, '_nhomg_location_detail', 'Digital Marketing Executive'),
(512, 108, '_nhomg_highlights', 'Làm quen với chiến dịch thương mại điện tử.\r\n\r\n\r\n\r\nPhân tích hành vi khách hàng.\r\n\r\n\r\n\r\nPhát triển kỹ năng nội dung và quảng cáo số.'),
(513, 108, '_nhomg_rating', '4.2'),
(514, 108, '_nhomg_photos', ''),
(515, 108, '_heateor_sss_meta', 'a:2:{s:7:\"sharing\";i:0;s:16:\"vertical_sharing\";i:0;}'),
