(519, 109, '_job_location', 'Remote'),
(520, 109, '_application', ''),
(521, 109, '_company_website', 'https://www.canva.com'),
(522, 109, '_nhomg_overview', 'Canva phát triển nền tảng thiết kế trực tuyến giúp người dùng tạo các sản phẩm hình ảnh, bài thuyết trình, tài liệu và nội dung truyền thông.'),
(523, 109, '_nhomg_key_skills', 'Figma\r\n\r\n\r\n\r\nUI Design và UX Research\r\n\r\n\r\n\r\nWireframing, Prototyping\r\n\r\n\r\n\r\nDesign System\r\n\r\n\r\n\r\nUsability Testing'),
(524, 109, '_nhomg_why_love', 'Bạn có thể kết hợp tư duy thiết kế với khả năng giải quyết vấn đề, tạo ra giao diện trực quan và giúp người dùng hoàn thành công việc dễ dàng hơn.'),
(525, 109, '_nhomg_location_detail', 'UI/UX Designer'),
(526, 109, '_nhomg_highlights', 'Phát triển tư duy thiết kế lấy người dùng làm trung tâm.\r\n\r\n\r\n\r\nXây dựng portfolio sản phẩm.\r\n\r\n\r\n\r\nPhối hợp cùng nhóm thiết kế và kỹ thuật.'),
(527, 109, '_nhomg_rating', '3.9'),
(528, 109, '_nhomg_photos', ''),
(529, 109, '_heateor_sss_meta', 'a:2:{s:7:\"sharing\";i:0;s:16:\"vertical_sharing\";i:0;}'),
