(534, 110, '_application', ''),
(535, 110, '_company_website', 'https://tiki.vn'),
(536, 110, '_nhomg_overview', 'Tiki là thương hiệu thương mại điện tử tại Việt Nam, cung cấp nền tảng mua sắm trực tuyến và các dịch vụ hỗ trợ hoạt động bán hàng, đặt hàng và giao nhận.'),
(537, 110, '_nhomg_key_skills', 'Phân tích yêu cầu nghiệp vụ\r\n\r\n\r\n\r\nSQL cơ bản\r\n\r\n\r\n\r\nBPMN, UML\r\n\r\n\r\n\r\nViết tài liệu SRS\r\n\r\n\r\n\r\nGiao tiếp và quản lý yêu cầu'),
(538, 110, '_nhomg_why_love', 'Bạn đóng vai trò kết nối giữa người dùng, bộ phận nghiệp vụ và đội ngũ phát triển để biến yêu cầu kinh doanh thành giải pháp phần mềm cụ thể.'),
(539, 110, '_nhomg_location_detail', 'Business Analyst (BA)'),
(540, 110, '_nhomg_highlights', 'Phát triển tư duy phân tích hệ thống.\r\n\r\n\r\n\r\nHọc cách làm việc với nhiều bộ phận.\r\n\r\n\r\n\r\nKết hợp kiến thức công nghệ và kinh doanh.'),
(541, 110, '_nhomg_rating', '3.8'),
