(548, 111, '_application', ''),
(549, 111, '_company_website', 'https://kpmg.com/vn/en/home.html'),
(550, 111, '_nhomg_overview', 'KPMG là mạng lưới doanh nghiệp cung cấp các dịch vụ kiểm toán, thuế và tư vấn cho nhiều tổ chức, doanh nghiệp thuộc các ngành nghề khác nhau.'),
(551, 111, '_nhomg_key_skills', 'Microsoft Excel, Word\r\n\r\n\r\n\r\nGiao tiếp và làm việc nhóm\r\n\r\n\r\n\r\nQuản lý hồ sơ\r\n\r\n\r\n\r\nHỗ trợ tuyển dụng\r\n\r\n\r\n\r\nTiếng Anh giao tiếp'),
(552, 111, '_nhomg_why_love', 'Bạn có thể tìm hiểu quy trình nhân sự trong môi trường doanh nghiệp chuyên nghiệp, đồng thời rèn luyện kỹ năng tổ chức, giao tiếp và quản lý công việc.'),
(553, 111, '_nhomg_location_detail', 'Human Resources Intern'),
(554, 111, '_nhomg_highlights', 'Phù hợp với người muốn bắt đầu sự nghiệp nhân sự.\r\n\r\n\r\n\r\nRèn luyện kỹ năng tổ chức và giao tiếp.\r\n\r\n\r\n\r\nCó cơ hội tìm hiểu quy trình tuyển dụng và quản lý nhân sự.'),
(555, 111, '_nhomg_rating', '3.5'),
